/**
 * @brief Estimate whether a call site is inside a backward edge's span.
 *
 * @param fn Function containing the call.
 * @param call Block ID containing the call site.
 * @return True if a backward edge spans the call site.
 */
// Use a backward edge spanning the call as a cheap estimate that the site may
// be hot.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement. You can change IR if it improves the results/makes things
// more clear. Also try to split long files (300+) into smaller thematic ones,
// like optimizer was before" Changes: Allow a larger inline candidate inside a
// bounded backedge span.
static bool in_loop_span(const IrFunction* fn, IrBlockId call) {
  for (IrBlockId b = call; b < fn->blocks.count; b++) {
    const IrBlockTerminator* term = &fn->blocks.data[b].terminator;

    if (term->type == IR_TERMINATOR_JUMP && term->value.jump_target <= call &&
        term->value.jump_target < b)
      return true;
  }

  return false;
}

void optimizer_transform_calls(Ctx* ctx) {
  DEBUG("Starting call transformation pass");

  // Share specialized bodies across sites that bind the same argument positions
  // and values.
  CallVariant variants[MAX_VARIANTS];
  size_t variant_count = 0;
  size_t function_count = ctx->ir.functions.count;
  for (IrFunctionId fid = 0; fid < function_count; fid++)
    optimizer_call_eliminate_tail_calls(ctx, fid);

  for (IrFunctionId fid = 0; fid < function_count; fid++) {
    size_t inlined = 0;

    for (IrBlockId bid = 0; bid < ctx->ir.functions.data[fid].blocks.count;
         bid++) {
      IrInstructionArray* instructions =
          &ctx->ir.functions.data[fid].blocks.data[bid].instructions;

      for (size_t i = 0; i < instructions->count;) {
        IrInstruction* call = &instructions->data[i++];
        // AI generated by: Codex (GPT-6.2-sol)
        // Prompt: "Remove builtin functions from the IR altogether (they should
        // now be handled by lowering to allow for their optimalization, no?).
        // Propagate these changes to the relevant systems (codegen, optimizer)"
        // Changes: Treat every CALL as a user function call.
        if (call->type != IR_INST_CALL || call->operands.call.id == fid ||
            call->operands.call.arg_count > MAX_PARAMETERS)
          continue;

        IrFunctionId original = call->operands.call.id;
        const IrFunction* callee = &ctx->ir.functions.data[original];

        if (inlined < 16 && optimizer_call_can_inline(callee)) {
          size_t before = instructions->count;
          optimizer_call_inline_call(ctx, fid, bid, i - 1, callee);
          i = i - 1 + instructions->count - (before - 1);
          inlined++;
          continue;
        }

        // The mask distinguishes literal arguments from values still required
        // at runtime.
        unsigned bound = 0;
        for (size_t a = 0; a < call->operands.call.arg_count; a++) {
          if (call->operands.call.args[a].type != IR_OP_VALUE)
            bound |= 1u << a;
        }

        if (!bound || !optimizer_call_can_specialize(callee)) {
          if (inlined < 16 &&
              optimizer_call_can_inline_cfg(
                  callee, in_loop_span(&ctx->ir.functions.data[fid], bid))) {
            optimizer_call_inline_cfg(ctx, fid, bid, i - 1, callee);

            inlined++;
            // The suffix will be processed in its new continuation block.
            break;
          }

          continue;
        }

        // The mask alone is insufficient for reuse: compare the bound literals
        // in the clone entry stores.
        IrFunctionId clone = IR_INVALID_ID;
        for (size_t v = 0; v < variant_count; v++) {
          if (variants[v].original != original || variants[v].bound != bound)
            continue;

          const IrInstruction* stores =
              ctx->ir.functions.data[variants[v].clone]
                  .blocks.data[0]
                  .instructions.data;

          bool matches = true;
          for (size_t a = 0; a < call->operands.call.arg_count; a++)
            if (bound & (1u << a)) {
              matches &= optimizer_call_same_constant(
                  call->operands.call.args[a],
                  (stores++)->operands.store.source);
            }

          if (matches) {
            clone = variants[v].clone;
            break;
          }
        }

        if (clone == IR_INVALID_ID) {
          if (variant_count == MAX_VARIANTS)
            continue;

          clone = optimizer_call_specialize(ctx, original, call, bound);
          variants[variant_count++] = (CallVariant){original, clone, bound};
        }

        // Compact arguments in place after selecting the clone; only its
        // unbound parameters remain.
        size_t written = 0;
        for (size_t a = 0; a < call->operands.call.arg_count; a++) {
          IrOperand argument = call->operands.call.args[a];

          if (bound & (1u << a))
            ir_free_operand(&argument);
          else
            call->operands.call.args[written++] = argument;
        }

        call->operands.call.arg_count = written;
        call->operands.call.id = clone;
      }
    }
  }
}
